type EventMap = {
  [eventName: string]: any;
};

class EventBus<T extends EventMap> {
  private listeners: { [K in keyof T]?: ((payload: T[K]) => void)[] } = {};

  subscribe<K extends keyof T>(eventName: K, listener: (payload: T[K]) => void): () => void {
    if (!this.listeners[eventName]) {
      this.listeners[eventName] = [];
    }
    this.listeners[eventName]!.push(listener);

    return () => {
      this.unsubscribe(eventName, listener);
    };
  }

  publish<K extends keyof T>(eventName: K, payload: T[K]): void {
    const listeners = this.listeners[eventName];
    if (listeners) {
      listeners.forEach(listener => listener(payload));
    }
  }

  private unsubscribe<K extends keyof T>(eventName: K, listener: (payload: T[K]) => void): void {
    const listeners = this.listeners[eventName];
    if (listeners) {
      const index = listeners.indexOf(listener);
      if (index !== -1) {
        listeners.splice(index, 1);
      }
    }
  }
}

// Example usage
interface Events {
  'user.created': { userId: string };
  'user.updated': { userId: string, newName: string };
}

const eventBus = new EventBus<Events>();

const unsubscribeUserCreated = eventBus.subscribe('user.created', (payload) => {
  console.log(`User created with ID: ${payload.userId}`);
});

eventBus.publish('user.created', { userId: '123' });

unsubscribeUserCreated();

eventBus.publish('user.updated', { userId: '123', newName: 'John Doe' });
```

### Explanation:
- **EventMap**: A generic type that maps event names to their corresponding payload types.
- **EventBus Class**:
  - **subscribe**: Adds a listener for a specific event and returns an unsubscribe function.
  - **publish**: Triggers all listeners for a specific event with the provided payload.
  - **unsubscribe**: Removes a listener from a specific event.
- **Example Usage**: Demonstrates how to use the EventBus with a specific set of events (`user.created` and `user.updated`).

