import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';

// Define the Zod schema for user profile update
const UserProfileUpdateSchema = z.object({
  name: z.string().min(1).max(50),
  email: z.string().email(),
  age: z.number().int().positive().lte(120),
});

// Server Action to update a user profile
export async function updateUserProfile(request: NextRequest) {
  try {
    // Parse the request body with Zod schema validation
    const data = await request.json();
    const parsedData = UserProfileUpdateSchema.parse(data);

    // Simulate updating the user profile in a database
    // Replace this with actual database update logic
    const updatedUser = {
      id: 1,
      name: parsedData.name,
      email: parsedData.email,
      age: parsedData.age,
    };

    // Return the updated user data as JSON
    return NextResponse.json(updatedUser, { status: 200 });
  } catch (error) {
    // Handle validation errors and other exceptions
    if (error instanceof z.ZodError) {
      // Serialize Zod validation errors for client-side handling
      return NextResponse.json(
        { error: 'Validation Error', details: error.issues },
        { status: 400 }
      );
    } else {
      // Handle other exceptions and serialize them safely
      return NextResponse.json(
        { error: 'Internal Server Error', message: error.message },
        { status: 500 }
      );
    }
  }
}

// Revalidate the path after updating the user profile
export const revalidate = 60; // Revalidate every 60 seconds
```

### Explanation:
1. **Zod Schema Validation**: The `UserProfileUpdateSchema` defines the structure and constraints for the user profile data. This ensures that only valid data is processed.
2. **Server Action**: The `updateUserProfile` function handles the incoming request, parses the JSON body using Zod, and simulates updating the user profile. If the data is invalid, it returns a validation error response. If an exception occurs, it returns a generic internal server error response.
3. **Revalidation**: The `revalidate` export specifies that the path should be revalidated every 60 seconds after the action is executed. This helps in ensuring that the updated data is reflected in subsequent requests.

This code follows the guidelines for full-stack software engineering, including TypeScript, Zod schema validation, and safe error handling.
